def sha256(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def main():
    if len(sys.argv) != 2:
        print(__doc__)
        return 2
    target = sys.argv[1]
    os.makedirs(target, exist_ok=True)
    target = os.path.abspath(target)

    # 1) manifest
    manifest_text = base64.b64decode("".join(MANIFEST_B64.split())).decode("utf-8")
    if sha256(manifest_text.encode("utf-8")) != MANIFEST_SHA256:
        print("ERROR: manifest checksum mismatch")
        return 1
    rows = {}
    for line in manifest_text.splitlines():
        line = line.strip()
        if not line:
            continue
        rel, size, dig = line.rsplit("|", 2)
        rows[rel] = (int(size), dig)
    if len(rows) != FILE_COUNT:
        print("ERROR: manifest row count %d != %d" % (len(rows), FILE_COUNT))
        return 1

    # 2) zip payload
    raw = base64.b64decode("".join(PAYLOAD_B64.split()))
    if len(raw) != ZIP_BYTES:
        print("ERROR: zip size %d != %d" % (len(raw), ZIP_BYTES))
        return 1
    if sha256(raw) != ZIP_SHA256:
        print("ERROR: zip checksum mismatch")
        return 1

    zf = zipfile.ZipFile(io.BytesIO(raw))
    names = set(zf.namelist())
    if names != set(rows):
        extra = sorted(names - set(rows))[:5]
        miss = sorted(set(rows) - names)[:5]
        print("ERROR: zip content != manifest  extra=%s missing=%s" % (extra, miss))
        return 1

    # 3) write + per-file verify, then re-verify each written file
    bad = []
    ok = 0
    for rel in sorted(rows):
        size, dig = rows[rel]
        data = zf.read(rel)
        if len(data) != size or sha256(data) != dig:
            bad.append(rel)
            continue
        dst = os.path.join(target, rel.replace("/", os.sep))
        os.makedirs(os.path.dirname(dst) or target, exist_ok=True)
        with open(dst, "wb") as f:
            f.write(data)
        with open(dst, "rb") as f:
            if sha256(f.read()) != dig:
                bad.append(rel)
                continue
        ok += 1

    if bad:
        print("ERROR: %d file(s) failed verification: %s" % (len(bad), bad[:10]))
        return 1
    print("RESTORED OK: %d / %d files -> %s" % (ok, FILE_COUNT, target))
    print("manifest_sha256:", MANIFEST_SHA256)
    print("zip_sha256     :", ZIP_SHA256)
    print("")
    print("Next: regenerate npm deps if needed:")
    print('    cd ".opencode" && npm install   # restores node_modules (@opencode-ai/plugin)')
    return 0


if __name__ == "__main__":
    sys.exit(main())
